function deny(reasonCode, nextAction = null) {
  return { decision: "deny", allowed: false, reasonCode, nextAction };
}
function allow() {
  return { decision: "allow", allowed: true, reasonCode: null, nextAction: null };
}
function guardPaymentVerification({ actorType }) {
  if (["llm", "jev"].includes(actorType)) {
    return deny("PAYMENT_VERIFICATION_FORBIDDEN_ACTOR");
  }
  if (actorType !== "human") {
    return deny("PAYMENT_VERIFICATION_REQUIRES_HUMAN");
  }
  return allow();
}
return {json:guardPaymentVerification({
  actorType:$json.actor_type ?? $json.actorType ?? null
})};

const verificationGuard=$json;
const input=$('Receive Payment Context').item.json;
const trigger=String(input.trigger_type ?? '');

const cents=(value)=>{
  if(value===null || value===undefined || value==='') return null;
  const n=Number(value);
  return Number.isFinite(n)?Math.round(n*100):null;
};

if(trigger==='proof_received'){
  const expected=cents(input.expected_amount);
  const extracted=cents(input.extracted_amount);
  let extractionStatus='unreadable';
  if(extracted!==null && expected!==null){
    extractionStatus=extracted===expected?'apparent_ok':'divergent';
  }else if(extracted!==null && expected===null){
    extractionStatus='apparent_ok';
  }

  const key='payment-proof:'+String(input.external_transaction_ref ?? input.source_event_id ?? input.proof_ref ?? input.customer_event_id);
  const operations=[
    {
      action:'UPSERT_PAYMENT_EVIDENCE',
      idempotency_key:key,
      customer_event_id:input.customer_event_id,
      payment_kind:input.payment_kind,
      expected_amount:input.expected_amount ?? null,
      extracted_amount:input.extracted_amount ?? null,
      extraction_status:extractionStatus,
      human_status:'pending',
      proof_ref:input.proof_ref ?? null,
      external_transaction_ref:input.external_transaction_ref ?? null,
      source_event_id:input.source_event_id ?? null
    },
    {
      action:'CREATE_HUMAN_TASK',
      task_type:'payment_verification',
      reason_code:extractionStatus==='divergent'?'PAYMENT_DIVERGENCE':'PAYMENT_VERIFICATION_REQUIRED',
      customer_event_id:input.customer_event_id,
      priority:extractionStatus==='divergent'?'high':'normal'
    }
  ];
  if(extractionStatus==='divergent'){
    operations.push({action:'ENABLE_HUMAN_LOCK',reason_code:'PAYMENT_DIVERGENCE'});
  }
  return {json:{
    status:'pending_human_verification',
    extraction_status:extractionStatus,
    payment_verified:false,
    operations,
    blockers:extractionStatus==='divergent'?['PAYMENT_DIVERGENCE']:[]
  }};
}

if(trigger==='human_verification'){
  if(!verificationGuard.allowed){
    return {json:{
      status:'denied',
      payment_verified:false,
      operations:[],
      guard:verificationGuard,
      blockers:[verificationGuard.reasonCode]
    }};
  }

  const paymentId=(input.current_payment?.id ?? input.payment_id ?? null);
  if(!paymentId){
    return {json:{status:'blocked',payment_verified:false,operations:[],guard:verificationGuard,blockers:['PAYMENT_ID_REQUIRED_FOR_VERIFICATION']}};
  }

  const decision=String(input.verification_decision ?? '').toLowerCase();
  if(!['verified','rejected'].includes(decision)){
    return {json:{status:'blocked',payment_verified:false,operations:[],guard:verificationGuard,blockers:['PAYMENT_VERIFICATION_DECISION_INVALID']}};
  }
  const current=input.current_payment ?? {};
  const operations=[{
    action:'VERIFY_PAYMENT',
    payment_id:paymentId,
    expected_verification_version:current.verification_version ?? 0,
    human_status:decision,
    verified_by:input.actor_ref ?? null,
    actor_type:'human'
  }];
  operations.push({
    action:'EMIT_EVENT',
    event_type:decision==='verified'?'payment_verified':'payment_rejected',
    customer_event_id:input.customer_event_id,
    payment_id:paymentId
  });
  return {json:{
    status:decision,
    payment_verified:decision==='verified',
    operations,
    guard:verificationGuard,
    blockers:[]
  }};
}

return {json:{status:'blocked',payment_verified:false,operations:[],blockers:['PAYMENT_TRIGGER_UNKNOWN']}};
